        snapshot = {
            "active_tank_x": 10,
            "active_tank_y": 0,
            "active_tank_z": 50,
            "leader_x": 4000,
            "leader_y": 4000,
            "leader_z": 0,
        }

        destination = behavior.party_support_peel_kite_destination(args, client, threat, snapshot)

        self.assertIsNotNone(destination)
        self.assertGreater(destination.x, 10)
